CREATE TABLE IF NOT EXISTS `roles` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `nom` VARCHAR(50) NOT NULL, `description` VARCHAR(255) DEFAULT NULL, `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uk_roles_nom` (`nom`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `roles` (`nom`, `description`) VALUES ('administrateur', 'Gestion complete'), ('directeur', 'Supervision'), ('professeur', 'Validation des memoires'), ('etudiant', 'Depot et consultation');

CREATE TABLE IF NOT EXISTS `filieres` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `nom` VARCHAR(150) NOT NULL, `code` VARCHAR(20) NOT NULL, `description` TEXT DEFAULT NULL, `statut` ENUM('active', 'inactive') DEFAULT 'active', `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP, `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uk_filieres_code` (`code`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `filieres` (`nom`, `code`, `description`, `statut`) VALUES ('Systeme Informatique et Logiciel', 'SIL', 'Formation informatique', 'active'), ('Reseaux Informatique et Telecommunication', 'RIT', 'Reseaux et telecom', 'active'), ('Systeme Industriel', 'SI', 'Electricite et automatisme', 'active'), ('Finance Comptabilite et Audit', 'FCA', 'Finance et comptabilite', 'active'), ('Banque Finance Assurance', 'BFA', 'Banque et assurance', 'active'), ('Management des Ressources Humaines', 'MRH', 'Gestion du capital humain', 'active'), ('Management Communication et Commerce', 'MCC', 'Marketing et commerce', 'active'), ('Entrepreneuriat et Gestion des Projets', 'EGP', 'Creation d entreprise', 'active'), ('Transport et Logistique', 'TL', 'Logistique et supply chain', 'active'), ('Agronomie', 'AGR', 'Production vegetale et animale', 'active'), ('Biotechnologie', 'BIO', 'Biologie appliquee', 'active'), ('Sciences Juridiques', 'SJ', 'Droit prive et public', 'active'), ('Communication et Relations Internationales', 'CRI', 'Communication et diplomatie', 'active');

CREATE TABLE IF NOT EXISTS `utilisateurs` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT, `role_id` INT UNSIGNED NOT NULL, `nom` VARCHAR(100) NOT NULL, `prenom` VARCHAR(100) NOT NULL, `email` VARCHAR(255) NOT NULL, `password` VARCHAR(255) NOT NULL, `telephone` VARCHAR(20) DEFAULT NULL, `avatar` VARCHAR(255) DEFAULT NULL, `niveau` VARCHAR(20) DEFAULT NULL, `statut` ENUM('actif', 'inactif', 'suspendu') DEFAULT 'actif', `derniere_connexion` TIMESTAMP NULL DEFAULT NULL, `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP, `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uk_utilisateurs_email` (`email`), KEY `idx_utilisateurs_role` (`role_id`), KEY `idx_utilisateurs_statut` (`statut`), CONSTRAINT `fk_utilisateurs_role` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

